# region: fold
def fold(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: emit
def emit(xs, factor=10):
    return [v * factor for v in xs]

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs):
    return [v * v for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: sift
def sift(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return sift(shape(digest(intake(emit(fold(raw))))))

